 "content": "def transform(grid):
    # Each horizontal monochrome bar represents one cell of its own color.
    # Pack the bars, in color order, into the 2x3 output.
    counts = {}
    for row in grid:
        c = 0
        while c < len(row):
            if row[c] == 0:
                c += 1
                continue
            color = row[c]
            counts[color] = counts.get(color, 0) + 1
            while c < len(row) and row[c] == color:
                c += 1
    values = []
    for color in sorted(counts):
        values.extend([color] * counts[color])
    values = (values + [0] * 6)[:6]
    return [values[:3], values[3:]]
