 "content": "def transform(grid):
    # The most frequent value is the background; count each horizontal
    # contiguous bar of the remaining colors as one output cell.
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    counts = {}
    for row in grid:
        c = 0
        while c < len(row):
            color = row[c]
            if color == background:
                c += 1
                continue
            counts[color] = counts.get(color, 0) + 1
            c += 1
            while c < len(row) and row[c] == color:
                c += 1
    values = []
    for color in sorted(counts, reverse=True):
        values.extend([color] * counts[color])
    values = (values + [0] * 6)[:6]
    return [values[:3], values[3:]]
